"""Write ``src/adcp/types/legacy_names.py``: upstream's published class names, bound to ours.

Reads the resolution ``survey/resolve_legacy_names.py`` produces and writes one re-export per
row. It decides nothing -- every row arrived already resolved by pointer, by signature or by
the ledger's own probe -- so this module is a renderer and holds no rule.
"""

from __future__ import annotations

import collections
import json
import pathlib

DOC = '''"""Upstream's published class names, bound to the class of ours denoting one subject.

**GENERATED by ``survey/emit_legacy_names.py`` -- do not edit.**

WHAT THIS IS, and it is only one thing: a NAME. Upstream's 9.6.1 wheel published a word; our
compiler names the same subject from its document and arrives at a different word. This module
binds theirs to ours so that code written against their wheel keeps importing. It declares no
class, it changes no accepted set, and it cannot -- an alias is a second spelling of one object.

**AND IT ASKS NO QUESTION ABOUT CORRECTNESS, WHICH IS THE POINT.** A gate stood in the alias
join refusing a name wherever upstream pinned a property our subject did not. It withheld 132
of upstream's own test files over ``status: Literal["completed"] = "completed"`` -- a pin the
document states nowhere, and one of the 867 invented defaults every one of which is attributed
to their generator. The diagnosis never needed the gate: bind the name, run the test, and a
test passing a field its document refuses fails AT VALIDATION with the keyword and the value in
the message. That failure is the finding, it belongs to the test, and
``survey/dropin/deselect.py`` is what declines it with a reason. A refusal here only hid the
diagnosis behind a missing name.

EVERY ROW IS RESOLVED BY MEASUREMENT AND NEVER BY SPELLING: the pointer both sides carry where
upstream's class has one, else the field-and-required signature, else the probe recorded in
``survey/name-decisions-9.6.1.json``. The population is upstream's published names that their
tests or their kept machinery actually import and that our surface does not already answer for.
"""'''


def main() -> int:
    rows = json.loads(pathlib.Path("/tmp/final_aliases.json").read_text())
    by_mod: dict[str, list[dict]] = collections.defaultdict(list)
    for row in rows:
        by_mod[row["module"]].append(row)

    imports: list[str] = []
    for mod in sorted(by_mod):
        for row in sorted(by_mod[mod], key=lambda r: r["name"]):
            stmt = f"from {mod} import {row['symbol']} as {row['name']}"
            # A generated re-export is as long as its two names make it, and `ruff format`
            # collapses a parenthesised single import back onto one line -- so the length is
            # not ours to wrap away and is annotated instead.
            flags = []
            if len(stmt) > 100:
                flags.append("E501")
            if row["name"].isupper():
                flags.append("N814")
            if flags:
                stmt += f"  # noqa: {', '.join(flags)} -- upstream published this spelling"
            imports.append(stmt)

    lines = [DOC, "", "from __future__ import annotations", ""]
    lines += sorted(imports)
    lines += ["", "__all__ = ["]
    lines += [f'    "{row["name"]}",' for row in sorted(rows, key=lambda r: r["name"])]
    lines += ["]", ""]

    out = pathlib.Path("src/adcp/types/legacy_names.py")
    out.write_text("\n".join(lines))
    print("wrote", out, len(rows), "names")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
